FuncDef.Code:
float opFiniteRepeatCenteredXYZ(inout vec3 p, float spacingX, float spacingY, float spacingZ, int repX, int repY, int repZ)
{
    vec3 spacing        = vec3(spacingX, spacingY, spacingZ);
    vec3 repetitions    = vec3(repX, repY, repZ);

    // centering
    p += 0.5 * repetitions * spacing;

    // cell index
    vec3 halfsize = spacing*0.5;
    vec3 evenCorrection = vec3(1.0);//floor(1.0 + mod(repetitions, 2.0));
    vec3 c = floor((p + evenCorrection * halfsize)/spacing);

    float cellIndex = c.x + c.y + PI * sin(c.x * c.y) + PI * sin(0.88 + c.x * c.y * c.z);

    p = p - spacing * clamp(round(p / spacing), vec3(0.0), repetitions);

    return cellIndex;
}
